head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


/* ======================================================================    
FUNCTION:      fn_IsValidDateComm    
RETURN:      입력되어있는 날짜가 타입에 맞는지 확인     
====================================================================== */
/**
 * @method
 * @name fn_IsValidDateComm
 * @description desc
 * @param {string} obj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_IsValidDateComm = function(obj) {
    var source = obj.getValue();
    if (source.length != 8) {
        return false;
    }
    var yy = source.substring(0, 4);
    var mm = source.substring(4, 6);
    var dd = source.substring(6, 8);
    if (mm < '10') {
        mm = mm.substring(1);
    }
    if (dd < '10') {
        dd = dd.substring(1);
    }
    var ny = parseInt(yy);
    var nm = parseInt(mm);
    var nd = parseInt(dd);
    if (!(Number(yy)) || (ny < 1000) || (ny > 9999)) {
        return false;
    }
    if (!(Number(mm)) || (nm < 1) || (nm > 12)) {
        return false;
    }
    var arr_d = new Array('31', '28', '31', '30', '31', '30', '31', '31', '30', '31', '30', '31');

    // 윤년2월달 날수    
    if (((ny % 4 == 0) && (ny % 100 != 0)) || (ny % 400 == 0)) {
        arr_d[1] = 29;
    }
    if (!(Number(dd)) || (nd < 1) || (nd > arr_d[nm - 1])) {
        return false;
    }
    return true;
};


/* =======================================================================
	FUNCTION : fn_CheckStringLength
	RETURN : 문자열 길이를 체크(boolean)
======================================================================== */
/**
 * @method
 * @name fn_CheckStringLength
 * @description desc
 * @param {string} obj desc
 * @param {string} len desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckStringLength = function(obj, len) {
    var objLength = 0;
    for (var i = 0; i < obj.getValue().length; i++) {
        var ch = escape(obj.getValue().charAt(i));
        objLength += scwin.fn_StrCharByte(ch);
    }
    if (objLength > len) {
        alert("제한길이 " + len + " Byte를 넘었습니다.");
        obj.setValue("");
        return false;
    } else {
        return true;
    }
};


/* =======================================================================
	FUNCTION : strCharByte
	RETURN : 문자가 unicode면 2를 일반코드면 1을 리턴
======================================================================== */
/**
 * @method
 * @name fn_StrCharByte
 * @description desc
 * @param {string} chStr desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_StrCharByte = function(chStr) {
    if (chStr.substring(0, 2) == '%u') {
        if (chStr.substring(2, 4) == '00') return 1;

        else return 2; //한글 
    } else if (chStr.substring(0, 1) == '%') {
        //alert (parseInt(chStr.substring(1,3), 16)); 
        if (parseInt(chStr.substring(1, 3), 16) > 127) return 2; //한글 

        else return 1;
    } else {
        return 1;
    }
};
/**
 * @method
 * @name fn_JuminCheck
 * @description desc
 * @param {string} it desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_JuminCheck = function(it) {
    var IDtot = 0;
    var IDAdd = "234567892345";
    for (i = 0; i < 12; i++) {
        IDtot = IDtot + it.substring(i, i + 1) * IDAdd.substring(i, i + 1);
    }
    IDtot = 11 - (IDtot % 11);
    if (IDtot == 10) {
        IDtot = 0;
    } else if (IDtot == 11) {
        IDtot = 1;
    }
    if (it.substring(12, 13) != IDtot) return true;
    return false;
};
